function closeMenu(){$('#sidebar').classList.remove('open');$('#scrim').hidden=true;$('#menu-button').setAttribute('aria-expanded','false');}
function closeSearch(){const dialog=$('#search-dialog');if(dialog.open)dialog.close();}
function openSearch(){const dialog=$('#search-dialog');if(!dialog.open)dialog.showModal();$('#global-search').value='';search('');$('#global-search').focus();}
function search(q){const query=norm(q.trim());$('#search-results').innerHTML=query?chapters.filter(c=>norm(Object.values(c).flat().join(' ')).includes(query)).slice(0,24).map(c=>{const text=[c.problem,c.technical,c.mechanism,c.example,c.math,c.implementation,c.expected,c.errors,c.tradeoffs,c.impacts,c.exercise,c.solution,c.interview,c.criterion,...c.commands,...c.files].join(' '),i=norm(text).indexOf(query),start=Math.max(0,i-65),excerpt=text.slice(start,start+210);return `<a class="search-result" href="${routeTo(c.id)}"><small>${levels[c.level]} · Capítulo ${pad(chapters.indexOf(c)+1)}</small><strong>${e(c.title)}</strong><p>${start?'…':''}${e(excerpt)}${text.length>start+210?'…':''}</p></a>`;}).join('')||'<div class="search-empty">Nenhum capítulo encontrado. Tente um termo mais amplo, em português ou inglês.</div>':`<div class="search-empty">Busque no texto completo de ${chapters.length} capítulos. Sugestões: <strong>idempotência</strong>, <strong>KV cache</strong>, <strong>custo</strong>, <strong>streaming</strong>.</div>`;}
function validateStudy(value){if(!value||typeof value!=='object'||value.version!==1)throw new Error('Formato incompatível. Importe uma exportação Atlas versão 1.');const ids=new Set(chapters.map(c=>c.id));const cleanList=x=>Array.isArray(x)?[...new Set(x.filter(i=>typeof i==='string'&&ids.has(i)))]:[];const notes={},quiz={};if(value.notes&&typeof value.notes==='object')for(const[id,note]of Object.entries(value.notes)){if(ids.has(id)&&typeof note==='string'){if(note.length>10000)throw new Error('Uma anotação ultrapassa 10.000 caracteres.');notes[id]=note;}}if(value.quiz&&typeof value.quiz==='object')for(const[id,correct]of Object.entries(value.quiz))if(ids.has(id)&&correct===true)quiz[id]=true;return {version:1,completed:cleanList(value.completed),favorites:cleanList(value.favorites),notes,quiz,last:ids.has(value.last)?value.last:null,theme:['auto','light','dark'].includes(value.theme)?value.theme:'auto'};}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copiado.');}catch{const area=document.createElement('textarea');area.value=text;area.style.cssText='position:fixed;left:-9999px';document.body.append(area);area.select();const ok=document.execCommand('copy');area.remove();toast(ok?'Copiado.':'Cópia indisponível neste navegador. Selecione o texto manualmente.');}}
function render(){closeSearch();const parts=location.hash.replace(/^#\/?/,'').split('/').map(x=>{try{return decodeURIComponent(x);}catch{return x;}}),view=parts[0]||'inicio',id=parts[1];currentChapter=view==='capitulo'&&chapterBy(id)?id:null;if(currentChapter){study.last=currentChapter;save();}document.title=currentChapter?`${chapterBy(id).title} — Atlas`:'Atlas — Engenharia de IA, por dentro.';let html;switch(view){case'inicio':html=home();break;case'trilha':html=track(id);break;case'capitulo':html=chapter(id);break;case'laboratorios':html=laboratories(id);break;case'glossario':html=glossary();break;case'codigo':html=codePage(id);break;case'estudo':html=studyPage();break;default:html=notFound();}$('#conteudo').innerHTML=html;nav();closeMenu();if(view==='laboratorios'&&id)renderLab();requestAnimationFrame(()=>{if(view==='capitulo'&&parts[2]){document.getElementById(parts[2])?.scrollIntoView();}else{window.scrollTo(0,0);}if(!$('#search-dialog').open)$('#conteudo').focus({preventScroll:true});});}
document.addEventListener('click',async event=>{const target=event.target.closest('button,a');if(!target)return;
if(target.classList.contains('skip')){event.preventDefault();$('#conteudo').focus();$('#conteudo').scrollIntoView();return;}
if(target.id==='search-button'){openSearch();return;}
if(target.id==='close-search'){closeSearch();return;}
if(target.id==='theme-button'){study.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';save();theme();return;}
if(target.id==='menu-button'){const open=!$('#sidebar').classList.contains('open');$('#sidebar').classList.toggle('open',open);$('#scrim').hidden=!open;target.setAttribute('aria-expanded',String(open));return;}
if(target.closest('#search-results')){closeSearch();return;}
if(target.hasAttribute('data-copy')){await copy(target.dataset.copy);return;}
if(target.hasAttribute('data-permalink')){await copy(location.href);return;}
if(target.hasAttribute('data-print')){window.print();return;}
if(target.hasAttribute('data-filter')){trackFilter=target.dataset.filter;$$('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===trackFilter)));$('#chapter-grid').innerHTML=chapters.filter(c=>trackFilter==='all'||c.level===Number(trackFilter)).map(chapterCard).join('');return;}
if(target.hasAttribute('data-favorite')){const id=target.dataset.favorite;study.favorites=study.favorites.includes(id)?study.favorites.filter(x=>x!==id):[...study.favorites,id];save();const on=study.favorites.includes(id);target.setAttribute('aria-pressed',String(on));target.textContent=on?'★ Favorito':'☆ Favoritar';toast(on?'Capítulo salvo nos favoritos.':'Favorito removido.');return;}
if(target.hasAttribute('data-complete')){const id=target.dataset.complete;study.completed=study.completed.includes(id)?study.completed.filter(x=>x!==id):[...study.completed,id];save();const on=study.completed.includes(id);$$('[data-complete]').filter(b=>b.dataset.complete===id).forEach(b=>{b.setAttribute('aria-pressed',String(on));b.textContent=on?'✓ Concluído · marcar como pendente':'○ Marcar evidência como concluída';});nav();toast(on?'Progresso atualizado. Continue praticando.':'Capítulo marcado como pendente.');return;}
if(target.hasAttribute('data-quiz')){const id=target.dataset.quiz,q=quizData[id],correct=Number(target.dataset.answer)===q[2];$$('[data-quiz]').forEach(b=>delete b.dataset.result);target.dataset.result=correct?'correct':'wrong';$('#quiz-feedback').textContent=(correct?'Correto. ':'Revise a hipótese. ')+q[3];if(correct){study.quiz[id]=true;save();}return;}
if(target.id==='export-study'){const blob=new Blob([JSON.stringify({...study,exported_at:new Date().toISOString()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='atlas-meu-estudo.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Estudo exportado para JSON.');return;}
if(target.id==='import-study'){$('#import-file').click();return;}
if(target.hasAttribute('data-workflow-step')){workflowStep=Number(target.dataset.workflowStep);renderLab();return;}
if(target.hasAttribute('data-workflow-next')){workflowStep=Math.min(workflow.length-1,workflowStep+1);renderLab();return;}
if(target.hasAttribute('data-workflow-prev')){workflowStep=Math.max(0,workflowStep-1);renderLab();return;}
});
document.addEventListener('input',event=>{const t=event.target;if(t.id==='global-search')search(t.value);if(t.id==='glossary-search')$('#glossary-grid').innerHTML=glossaryTerms(t.value);if(t.dataset.notes){if(t.value.length>10000){t.value=t.value.slice(0,10000);toast('Limite de 10.000 caracteres por capítulo.');}study.notes[t.dataset.notes]=t.value;save();}if(t.closest('[data-active-lab]'))renderLab();});
document.addEventListener('change',async event=>{const t=event.target;if(t.id==='code-chapter')location.hash='#/codigo/'+t.value;if(t.closest('[data-active-lab]'))renderLab();if(t.id==='import-file'&&t.files[0]){try{if(t.files[0].size>1048576)throw new Error('Arquivo maior que 1 MiB.');const imported=validateStudy(JSON.parse(await t.files[0].text()));study.completed=[...new Set([...study.completed,...imported.completed])];study.favorites=[...new Set([...study.favorites,...imported.favorites])];study.notes={...study.notes,...imported.notes};study.quiz={...study.quiz,...imported.quiz};save();render();toast('Estudo importado e combinado com os dados locais.');}catch(err){toast('Importação recusada: '+err.message);}}});
document.addEventListener('keydown',event=>{const typing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();openSearch();}if(event.key==='/'&&!typing&&!$('#search-dialog').open){event.preventDefault();openSearch();}if(event.key==='Escape'){if($('#search-dialog').open){event.preventDefault();closeSearch();}closeMenu();}if(event.key==='ArrowDown'&&document.activeElement?.id==='global-search'){$('#search-results a')?.focus();event.preventDefault();}});
$('#scrim').addEventListener('click',closeMenu);
$('#search-dialog').addEventListener('cancel',event=>{event.preventDefault();closeSearch();});
$('#search-dialog').addEventListener('click',event=>{if(event.target===$('#search-dialog')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.target.close();}});
let printedDetails=[];window.addEventListener('beforeprint',()=>{printedDetails=$$('details:not([open])');printedDetails.forEach(d=>d.open=true);});window.addEventListener('afterprint',()=>printedDetails.forEach(d=>d.open=false));
window.addEventListener('hashchange',()=>{if(data)render();});
try{const response=await fetch(new URL('./data.json',import.meta.url));if(!response.ok)throw new Error('Falha ao carregar conteúdo: HTTP '+response.status);data=await response.json();chapters=data.chapters;study=validateStudy(study);theme();render();}catch(err){$('#conteudo').innerHTML=`<div class="page"><h1>O conteúdo não carregou.</h1><p>${e(err.message)}</p><p>Sirva esta pasta por HTTP; abrir index.html como file:// não permite carregar os módulos. Na raiz do projeto:</p>${codeBox('make manual-dev')}<p>Se o problema continuar, verifique o console e se data.json foi produzido por <code>python3 apps/manual/build.py</code>.</p></div>`;}
